    },
    {
      "card_ids": ["C16"],
      "claim": "Nimodipine, a highly lipophilic drug, had mean absolute oral bioavailability of 15.9% with many values below 20%, supporting low F for lipophilic poorly absorbed drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Nitrendipine, a lipophilic dihydropyridine, had absolute oral bioavailability of 10.7 ± 4.7% after a 20 mg tablet, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Colesevelam, a non-absorbed polymer, showed negligible systemic bioavailability, illustrating that drugs designed for local gastrointestinal action can have extremely low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol, a locally acting oral agent, had very low bioavailability after oral administration, supporting low systemic F for locally acting oral drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
